# PTX source for fp16 sum‑reduction over dimension 1 (shape B×D1×D2 → B×1×D2)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry reduce_sum_fp16(
    .param .u64 input_ptr,   // const half* __restrict__
    .param .u64 output_ptr,  // half* __restrict__
    .param .u32 batch,       // B
    .param .u32 dim1,        // D1  (reduced dimension)
    .param .u32 dim2         // D2
)
{
    // ----------------------------------------------------------------------
    // registers
    // ----------------------------------------------------------------------
    .reg .pred  %p<5>;
    .reg .b32   %r<20>;
    .reg .b64   %rd<12>;
    .reg .f16   %f16tmp;
    .reg .f32   %sum, %val;

    // ----------------------------------------------------------------------
    // load kernel parameters
    // ----------------------------------------------------------------------
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u32 %r1, [batch];
    ld.param.u32 %r2, [dim1];
    ld.param.u32 %r3, [dim2];

    // ----------------------------------------------------------------------
    // thread / block indices
    // ----------------------------------------------------------------------
    mov.u32 %r4, %ctaid.x;          // batch index  (0 .. B‑1)
    mov.u32 %r5, %ctaid.y;          // dim2 index   (0 .. D2‑1)
    mov.u32 %r6, %tid.x;            // lane index   (0 .. blockDim.x‑1)
    mov.u32 %r7, %ntid.x;           // blockDim.x   (constant for this launch)

    // ----------------------------------------------------------------------
    // bounds check – if outside the logical grid just return
    // ----------------------------------------------------------------------
    setp.ge.u32 %p0, %r4, %r1;
    setp.ge.u32 %p1, %r5, %r3;
    or.pred %p0, %p0, %p1;
    @%p0 bra DONE;

    // ----------------------------------------------------------------------
    // each thread accumulates a partial sum over dim1 using a stride of blockDim.x
    // ----------------------------------------------------------------------
    mov.f32 %sum, 0f0;               // accumulator in fp32
    mov.u32 %r8, %r6;                // i = threadIdx.x

LOOP_START:
    setp.ge.u32 %p2, %r8, %r2;       // if i >= dim1 -> exit loop
    @%p2 bra REDUCE;

    // address = ((batch*dim1 + i) * dim2 + dim2Idx) * sizeof(half)
    mul.lo.u32 %r9, %r4, %r2;        // batch * dim1
    add.u32 %r9, %r9, %r8;           // + i  -> (batch*dim1 + i)
    mul.lo.u64 %rd3, %r9, %r3;       // * dim2
    add.u64 %rd3, %rd3, %r5;         // + dim2Idx
    mul.lo.u64 %rd3, %rd3, 2;        // * sizeof(half) = 2

    add.u64 %rd4, %rd1, %rd3;        // global address of element
    ld.global.f16 %f16tmp, [%rd4];
    cvt.f32.f16 %val, %f16tmp;
    fadd.rn.f32 %sum, %sum, %val;   // sum += val

    // i += blockDim.x
    add.u32 %r8, %r8, %r7;
    bra LOOP_START;

    // ----------------------------------------------------------------------
    // intra‑block reduction (tree reduction in shared memory)
    // ----------------------------------------------------------------------
REDUCE:
    .shared .align 4 .b32 sdata[256];   // enough for max blockDim.x = 256

    // store partial sum into shared memory
    st.shared.b32 [sdata + %r6*4], %sum;
    bar.sync 0;

    // reduction tree: halve the active threads each iteration
    mov.u32 %r10, %r7;               // stride = blockDim.x
REDU_LOOP:
    shr.u32 %r10, %r10, 1;           // stride >>= 1
    setp.lt.u32 %p3, %r6, %r10;      // if tid < stride
    @%p3 {
        ld.shared.b32 %val, [sdata + %r6*4];
        ld.shared.b32 %f16tmp, [sdata + (%r6 + %r10)*4];
        // reinterpret f16tmp bits as fp32 for addition (both are fp32 values)
        // they are already fp32, just add
        fadd.rn.f32 %val, %val, %f16tmp;
        st.shared.b32 [sdata + %r6*4], %val;
    }
    bar.sync 0;
    setp.ne.u32 %p4, %r10, 0;
    @%p4 bra REDU_LOOP;

    // ----------------------------------------------------------------------
    // thread 0 writes the final result (convert back to fp16)
    // ----------------------------------------------------------------------
    setp.eq.u32 %p5, %r6, 0;
    @%p5 {
        // final sum is in shared[0] (fp32)
        ld.shared.b32 %val, [sdata];
        cvt.f16.f32 %f16tmp, %val;

        // output address = ((batch * dim2) + dim2Idx) * sizeof(half)
        mul.lo.u64 %rd5, %r4, %r3;    // batch * dim2
        add.u64 %rd5, %rd5, %r5;      // + dim2Idx
        mul.lo.u64 %rd5, %rd5, 2;     // *2
        add.u64 %rd6, %rd2, %rd5;     // output ptr + offset
        st.global.f16 [%rd6], %f16tmp;
    }

DONE:
    ret;
}
'''

import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim   # kept for API compatibility; kernel always reduces dim‑1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "kernel only supports fp16"
        B, D1, D2 = x.shape
        out = torch.empty(B, 1, D2, dtype=torch.float16, device=x.device)

        # raw pointers
        inp_ptr = x.data_ptr()
        out_ptr = out.data_ptr()

        # launch PTX kernel
        module = ptx_load(PTX_SOURCE)
        grid  = (B, D2, 1)          # one block per (batch, dim2) pair
        block = (256, 1, 1)         # 256 threads per block (covers D1=4096)
        args = [inp_ptr, out_ptr, B, D1, D2]
        ptx_launch(module, "reduce_sum_fp16", grid, block, args)

        return out
